def transform(grid):
    """Project interior markers through matching perimeter rail segments."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # The most frequent color is the field; the prominent non-field border
    # color forms paired segments on opposite sides.
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    edge_counts = Counter(
        out[r][c]
        for r in range(h) for c in range(w)
        if (r == 0 or r == h - 1 or c == 0 or c == w - 1)
        and out[r][c] != bg
    )
    rail = edge_counts.most_common(1)[0][0]

    def segments(values):
        result = []
        for value in values:
            if not result or value != result[-1][-1] + 1:
                result.append([value])
            else:
                result[-1].append(value)
        return result

    sides = {
        "left": segments([r for r in range(h) if out[r][0] == rail]),
        "right": segments([r for r in range(h) if out[r][w - 1] == rail]),
        "top": segments([c for c in range(w) if out[0][c] == rail]),
        "bottom": segments([c for c in range(w) if out[h - 1][c] == rail]),
    }
    opposite = {"left": "right", "right": "left", "top": "bottom", "bottom": "top"}

    markers = [
        (r, c, out[r][c])
        for r in range(1, h - 1) for c in range(1, w - 1)
        if out[r][c] != bg and out[r][c] != rail
    ]

    for r, c, color in markers:
        # A marker belongs to the perimeter segment whose along-edge
        # coordinate matches it. Its corresponding position on the opposite
        # segment receives a full beam; the marker's own beam points to its
        # aligned edge.
